content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-008

=== 用户原始指令 (query.txt) ===
弄个信用卡积分卡片吧，文字叠在背景图上那种，点一下能跳到app里，能读积分到期日历，看到已兑换

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个信用卡积分卡片吧，文字叠在背景图上那种，点一下能跳到app里，能读积分到期日历，看到已兑换",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "title": {
              "type": "string",
              "description": "信用卡积分到期提醒日程标题",
              "sampleValue": "积分到期提醒"
            },
            "description": {
              "type": "string",
              "description": "即将到期的信用卡积分数量展示文本",
              "sampleValue": "18,800积分"
            },
            "dtStart": {
              "type": "string",
              "description": "积分到期日期展示文本",
              "sampleValue": "07月30日"
            },
            "dtEnd": {
              "type": "string",
              "description": "积分到期截止时间展示文本",
              "sampleValue": "23:59"
            }
          },
          {
            "title": {
              "type": "string",
              "description": "信用卡积分已兑换记录标题",
              "sampleValue": "已兑换记录"
            },
            "description": {
              "type": "string",
              "description": "已兑换的信用卡积分数量展示文本",
              "sampleValue": "5,200积分"
            },
            "dtStart": {
              "type": "string",
              "description": "最近一次积分兑换日期展示文本",
              "sampleValue": "07月02日"
            },
            "dtEnd": {
              "type": "string",
              "description": "最近一次积分兑换时间展示文本",
              "sampleValue": "10:20"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_watermark.png",
      "description": "轻量水印背景图，适合作为文字叠加的低干扰背景层，用于日程和账务类摘要卡片。"
    }
  ]
}

